import { EmbedBuilder } from 'discord.js'
import { isFinished, forMeson } from './meson.js'

// =============================================================================
//   Shared helpers
// =============================================================================

/** Embed side-bar colours. */
const COLOR = {
  ok: 0x1fa97f,       // done (also: wallet with no unfinished swaps)
  pending: 0xe0a324,  // still moving (also: wallet with unfinished swaps)
  bad: 0xd94f4f,      // failed / expired / unlocked / cancelled, not-found
  limited: 0x8a8f98,  // status unavailable (relayer stand-in while the explorer is down)
}

/** Discord renders <t:unix:f> in the reader's own timezone. */
const ts = (date, style = 'f') => (date ? `<t:${Math.floor(date.getTime() / 1000)}:${style}>` : '—')

/** Inline-code a value (or an em dash if empty). */
const code = (v) => (v ? `\`${v}\`` : '—')

/** Inline-code values, comma separated; past `max` the rest are only counted, so a long paste cannot push a message over Discord's length limit. */
function codeList (values, max = 5) {
  const shown = values.slice(0, max).map(code).join(', ')
  return values.length > max ? `${shown} and ${values.length - max} more` : shown
}

/** Embed colour for a status: red if not ok, green if done, amber while moving. */
function statusColor (status) {
  if (!status.ok) return COLOR.bad
  return status.done ? COLOR.ok : COLOR.pending
}

// =============================================================================
//   Swap details embed
// =============================================================================

/** "Solana" + address, as one embed field value (amount and token are in the Amount field). `limited`: the relayer stand-in, which has no addresses — said, so the gap does not look like a missing wallet. */
function sideValue (side, limited = false) {
  const lines = [`**${side.chain}**`]
  if (side.address) {
    lines.push(side.addressUrl ? `[${side.address}](${side.addressUrl})` : code(side.address))
  } else if (limited) {
    lines.push('_wallet not available_')
  }
  return lines.join('\n')
}

/** Ends the title of a details embed built from the relayer stand-in (`swap.limited`) — readSwapEmbed reads it back after a restart. */
const LIMITED_TAG = '(limited details)'

/** The "⚠️ Limited details" text on an embed from the relayer stand-in. `updatesHere`: the embed is followed (tickets), so the full details replace it once the explorer is back. */
const limitedNotice = (updatesHere) =>
  'Meson\'s explorer is temporarily unavailable, so the status can\'t be confirmed yet. ' +
  (updatesHere ? 'This message will update automatically once it\'s back.' : 'Look the swap up again later for the full details.')

/** Discord's limit on one embed field's value. */
const FIELD_MAX = 1024

/** The order steps are listed in the transaction hashes field; any other step goes last, in API order. */
const STEP_ORDER = ['posted', 'bonded', 'locked', 'executed', 'requesting', 'releasing', 'released', 'unlocked', 'cancelled']

/**
 * One entry per step (posted, bonded, …) for the transaction hashes field: its successful transaction, or — while it has only failed — its latest attempt, labelled "(failed)" by txValue.
 * Failed retries next to a success are not listed, so a release retried many times cannot push the successful hash out of the field; every attempt is still on the Meson explorer.
 * The API lists events in no reliable order (CANCELLED before EXECUTED has been seen) and without timestamps, so steps are sorted by STEP_ORDER; among a step's failed attempts the last listed is taken as the latest.
 */
function txSteps (events) {
  const steps = new Map()
  for (const e of events) {
    const step = String(e.name).split(':')[0].toLowerCase()
    if (!steps.has(step)) steps.set(step, { step, ok: null, failed: [] })
    const s = steps.get(step)
    if (String(e.name).toUpperCase().includes('FAILED')) s.failed.push(e)
    else s.ok = e
  }
  const rank = (s) => (STEP_ORDER.includes(s.step) ? STEP_ORDER.indexOf(s.step) : STEP_ORDER.length)
  return [...steps.values()].sort((a, b) => rank(a) - rank(b))
}

/**
 * The source-side and destination-side transaction hashes, with links. Trimmed by whole steps to fit a field — a raw character cut could split a link.
 *
 * The release is one entry that moves releasing → releasing (confirming) → released: the hashless RELEASING request until a release transaction exists, then that transaction, called "released" only once it has confirmed.
 */
function txValue (swap) {
  if (!swap.events.length) return '_no on-chain transactions yet_'
  const finished = isFinished(swap.status)
  const steps = txSteps(swap.events)
  const hasRelease = steps.some((s) => s.step === 'released')
  let out = ''
  for (const s of steps) {
    if (s.step === 'releasing' && hasRelease) continue
    const e = s.ok ?? s.failed.at(-1)
    // Some events carry no hash yet (e.g. REQUESTING, RELEASING: asked for, not on-chain) — once the swap is finished none will come, so they are left out.
    if (!e.hash && finished) continue
    // A release still confirming, or only failed so far (being retried), is not "released" yet.
    const name = s.step === 'released' && !(s.ok && !s.ok.pending) ? 'releasing' : s.step
    const link = !e.hash ? '_no transaction yet_' : e.url ? `[${e.hash}](${e.url})` : code(e.hash)
    // A step with only failed attempts says so — its hash alone would read as if the step had gone through.
    const note = `${s.ok ? '' : ' (failed)'}${e.pending ? ' (confirming)' : ''}`
    const entry = `**${name}**${note}\n${link}`
    const next = out ? `${out}\n${entry}` : entry
    if (next.length > FIELD_MAX - 2) return `${out}\n…`
    out = next
  }
  return out || '_no on-chain transactions yet_'
}

/** The "⚠️ Network notice" text: which of the swap's chains Meson cannot reach right now. */
function buildChainNotice (chains) {
  const names = chains.map((c) => `**${c}**`).join(' and ')
  return `${names} ${chains.length > 1 ? 'are' : 'is'} having network problems right now, which can delay this swap.`
}

/**
 * The swap details embed — posted in tickets and by /meson-query.
 * @param {Awaited<ReturnType<import('./meson.js').lookupSwap>>} swap
 * @param {{requestedBy?: string, sourceNote?: string, serial?: number|null, withSupportNote?: boolean, updatesHere?: boolean}} [opts] `serial` numbers the embed ("Meson swap #2") when a ticket has several swaps; `withSupportNote` adds the support note for /meson-query, whose answer gets no 🔎 reply; `updatesHere` says, on a limited embed, that the full details will replace it.
 */
export function buildSwapEmbed (swap, opts = {}) {
  const s = swap.status
  // From the relayer stand-in the status is a guess (no "still confirming", no failed attempts — a confirming release would read as Done), so none is shown: no status word, colour, reason or support note until the explorer's full details replace it.
  const heading = swap.limited ? `Status unavailable ${LIMITED_TAG}` : `${s.label}${s.star}`
  const embed = new EmbedBuilder()
    .setColor(swap.limited ? COLOR.limited : statusColor(s))
    .setTitle(`Meson swap${opts.serial ? ` #${opts.serial}` : ''} — ${heading}`)
    .setURL(swap.explorerUrl)
    .setDescription(swap.limited ? null : [s.detail, opts.withSupportNote ? s.supportNote : null].filter(Boolean).join('\n\n') || null)

  if (swap.limited) embed.addFields({ name: '⚠️ Limited details', value: limitedNotice(opts.updatesHere) })

  // Only on unfinished swaps (meson.js addChainHealth); it disappears on the next re-check once the chain recovers.
  if (swap.troubledChains?.length) embed.addFields({ name: '⚠️ Network notice', value: buildChainNotice(swap.troubledChains) })

  embed.addFields(
      { name: 'From', value: sideValue(swap.from, swap.limited), inline: true },
      { name: 'To', value: sideValue(swap.to, swap.limited), inline: true },
      { name: 'Amount', value: `${swap.from.amount} ${swap.from.token} → ${swap.to.amount} ${swap.to.token}` },
      // A transaction the relayer lists may still be confirming (it has no flag for that), so the list says so.
      { name: swap.limited ? 'Transactions found so far (may still be confirming)' : 'Transaction hashes', value: txValue(swap) },
    )

  // The relayer stand-in has no request time, and its notice already says so.
  if (!swap.limited) embed.addFields({ name: 'Timing', value: `Requested ${ts(swap.requestedAt)}` })

  embed.addFields({ name: 'Explorer link', value: swap.explorerUrl })

  const footer = [opts.sourceNote, opts.requestedBy ? `requested by ${opts.requestedBy}` : null]
    .filter(Boolean)
    .join(' · ')
  embed.setFooter({ text: footer || 'Meson Explorer' })

  return embed
}

// =============================================================================
//   Plain-text messages
// =============================================================================

/**
 * Plain-text reply to a new swap's details while it is still moving normally (status.ok, not finished) — posted by watch.js.
 * `serial` matches the "#n" on the details embed when a ticket has several swaps, as on the closing message.
 */
export function buildProcessingMessage ({ serial = null } = {}) {
  return `⏳ ${serial ? `**Swap #${serial}** · ` : ''}Your transaction is currently being processed, please wait patiently. ` +
    'We confirm that your assets are safe and the transaction will be completed shortly.'
}

/**
 * Plain-text reply to a swap's details while the support team has to step in (stuck, Expired, Unlocked, Failed) — posted by watch.js in place of the ⏳.
 * `serial` matches the "#n" on the details embed when a ticket has several swaps.
 */
export function buildSupportMessage (note, { serial = null } = {}) {
  return `🔎 ${serial ? `**Swap #${serial}** · ` : ''}${note}`
}

/** Private reply to /meson-query used outside the REPLY_CATEGORY_IDS categories. */
export const QUERY_WRONG_CHANNEL_MESSAGE = '🚫 `/meson-query` can only be used in support ticket channels.'

/** Last line of a closing message once every swap in the ticket is finished. */
export const CLOSING_SOON =
  '-# This ticket will be closed soon. If you still need help, our support team will respond to your message at the earliest or within 3-12hrs.'

/**
 * The closing note posted (as plain text, not an embed) as a reply to the swap details once a swap has finished (Done / Released → ✅, Cancelled → ↩️), or null if it has not.
 *
 * @param {{serial?: number|null, closingSoon?: boolean, kind?: 'completed'|'cancelled'|null}} [opts] `serial` matches the "#n" on the details embed when a ticket has several swaps; `closingSoon` (default true) is false while other swaps in the ticket are still open, so we do not promise the ticket is about to close; `kind` (default: what the swap's status calls for, outcomeKind) keeps a posted message's own outcome when it is only re-rendered (syncFollowUps).
 */
export function buildOutcomeMessage (swap, { serial = null, closingSoon = true, kind = outcomeKind(swap.status) } = {}) {
  const tag = serial ? ` — Swap #${serial}` : ''
  const footer = closingSoon ? CLOSING_SOON : null
  if (kind === 'completed') {
    return [
      `**✅ Transaction Completed${tag}**`,
      '',
      'Your transaction has been completed. Please check your **receiving address** for the funds.',
      footer,
    ].filter((l) => l !== null).join('\n')
  }
  if (kind === 'cancelled') {
    return [
      `**↩️ Transaction Cancelled${tag}**`,
      '',
      'Your transaction has been cancelled and the funds have been returned to your **sending address**.',
      footer,
    ].filter((l) => l !== null).join('\n')
  }
  return null
}

/**
 * Which closing message a status calls for: 'completed' (Done, or Released — before the LP executed, as complete as Done for the user: ✅), 'cancelled' (↩️), or null while the swap is not finished.
 * A finished swap can still change outcome on Meson (seen 2026-11-24: Cancelled, then released → Done), so a posted closing message is compared with this (watchSwap).
 */
export function outcomeKind (status) {
  if (status.label === 'Done' || status.label === 'Released') return 'completed'
  if (status.label === 'Cancelled') return 'cancelled'
  return null
}

/** Plain-text reply when a user pastes swap-shaped text that Meson does not know. */
export function buildSwapNotFoundMessage (queries) {
  return [
    `❓ I couldn't find a Meson swap for ${codeList(queries)}.`,
    // The server also supports other projects, so the reply must not read as if the user got something wrong. Small text (-#): the first line is the answer, this is the explanation.
    '-# This only checks swaps made through Meson. If this is a Meson swap, please double-check the **swap ID**, **transaction hash** or **explorer link**, as a new swap can take a moment to appear. ' +
      'Otherwise, our support team will respond here.',
  ].join('\n')
}

/**
 * The plain-text notices posted (once per ticket each) when Meson cannot answer after the quick retries; the message is still retried and answered as usual once Meson is back.
 * `wallet`: a wallet's swap list could not be read (the server's other project asks for wallets too, which is accepted). `swap`: a swap ID / hash / link could not be looked up, not even on Meson's relayer.
 */
const OUTAGE_NOTICES = {
  wallet: 'Meson\'s wallet address lookup is temporarily unavailable, so we can\'t check your address right now. If this is about a Meson swap, please share the source transaction hash, a blockchain explorer link, the Meson swap ID or the Meson explorer link.',
  swap: 'Meson\'s explorer isn\'t responding right now. We\'ll keep trying and post your swap details here as soon as it\'s back.',
}

/** The outage notice of this kind ('wallet' or 'swap') — read back after a restart by outageNoticeKind. */
export const buildOutageNotice = (kind) => OUTAGE_NOTICES[kind]

// =============================================================================
//   Wallet embeds
// =============================================================================

/** Status icon on each row of the wallet list; any status not here — Requesting, Posted, Bonded, Locked — gets ⚪, and a stuck Releasing swap gets 🔴. A listed swap that has finished since keeps its row with the icon of its closing message (🟢 for ✅, ↩️), so row 1) stays Swap #1. */
const STATUS_EMOJI = {
  Releasing: '🟡',
  Pending: '⚪',
  Failed: '🔴',
  Expired: '🔴',
  Unlocked: '🔴',
  Done: '🟢',
  Released: '🟢',
  Cancelled: '↩️',
}

/** A wallet-list row's heading: its number (= the swap's "#n" in the ticket), icon and status, e.g. "1) 🟡 Releasing". */
function walletRowName (swap, n) {
  const emoji = swap.status.stuck ? '🔴' : STATUS_EMOJI[swap.status.label] ?? '⚪'
  return `${n}) ${emoji} ${swap.status.label}${swap.status.star}`
}

/**
 * A wallet-list row's body: just the swap ID, linked to its explorer page.
 * Route, amounts and request time are on the swap's own details embed, posted as a reply to the list.
 */
const walletRowValue = (swap) => `[${swap.swapId}](${swap.explorerUrl})`

/**
 * Rows per embed: Discord allows 25 fields per embed, one is "Checked", and ~150 chars per row keeps a message far below its 6000-character cap.
 */
const ROWS_PER_EMBED = 20

/**
 * A wallet embed's title from how many of its listed swaps are still unfinished; `part` ("2/3") only when the list is split over several messages.
 */
function walletTitle (open, total, part) {
  const title = !total
    ? 'No open Meson swaps for this wallet'
    : !open
      ? 'All Meson swaps for this wallet are now finished'
      : open === total
        ? `Unfinished Meson swaps for this wallet: ${total}`
        : `Unfinished Meson swaps for this wallet: ${open} of ${total}`
  return part ? `${title} (${part})` : title
}

/**
 * Posted by ticket auto-detect when the ticket has a wallet address but no swap ID or hash: only that wallet's swaps that are not finished (Done, Released or Cancelled), so a long history of fine past swaps does not bury the one that is actually the problem.
 * Each row is the swap's number, status and linked swap ID; every listed swap is then posted as its own details embed in reply (tickets.js postWalletSwaps), numbered alike, and the list is re-listed as their statuses change (relistWalletEmbeds).
 * Every unfinished swap is listed — over several embeds (send one per message) if there are more than ROWS_PER_EMBED.
 *
 * @param {string} address
 * @param {Awaited<ReturnType<import('./meson.js').listUnfinishedSwapsForAddress>>} result
 * @param {{sourceNote?: string, missed?: string[]}} [opts] `missed`: IDs the user pasted that did not resolve, which is why the wallet is shown instead
 * @returns {EmbedBuilder[]}
 */
export function buildUnfinishedAddressEmbeds (address, result, opts = {}) {
  const { swaps, scanned, since, stoppedBy } = result
  const chunks = []
  for (let i = 0; i < swaps.length; i += ROWS_PER_EMBED) chunks.push(swaps.slice(i, i + ROWS_PER_EMBED))
  if (!chunks.length) chunks.push([])
  const open = swaps.filter((s) => !isFinished(s.status)).length

  const embeds = chunks.map((rows, i) => {
    const embed = new EmbedBuilder()
      .setColor(open ? COLOR.pending : COLOR.ok)
      .setTitle(walletTitle(open, swaps.length, chunks.length > 1 ? `${i + 1}/${chunks.length}` : null))
      .setURL(`https://explorer.meson.fi/address/${forMeson(address)}`)
    if (i === 0) {
      // The wallet is a fallback — say why it is being shown instead of a swap.
      const missed = opts.missed?.length
        ? `\n\nCould not find a swap for ${codeList(opts.missed)}${swaps.length ? ', so here are this wallet\'s unfinished swaps instead' : ''}.`
        : ''
      // The server also supports other projects, so "nothing here" must say it only covers Meson.
      const scope = swaps.length ? '' : '\n\nThis only checks swaps made through Meson. If your issue is with a specific Meson swap, please send its swap ID or transaction hash.'
      embed.setDescription(`${code(address)}${missed}${scope}`)
    }
    rows.forEach((swap, j) => embed.addFields({ name: walletRowName(swap, i * ROWS_PER_EMBED + j + 1), value: walletRowValue(swap) }))
    return embed
  })
  const embed = embeds[embeds.length - 1] // the closing note goes on the last one

  // Say how far back we looked, so "none" is not read as "never had a problem".
  const scope = stoppedBy === 'end'
    ? `all ${scanned} swap(s) this wallet has ever made`
    : stoppedBy === 'age'
      ? `${scanned} swap(s) since ${ts(since, 'D')}`
      : `the ${scanned} most recent swap(s) — older ones were not checked`
  embed.addFields({ name: 'Checked', value: `${scope}. Swaps already completed or cancelled are not listed.` })

  const footer = [opts.sourceNote].filter(Boolean).join(' · ')
  embed.setFooter({ text: footer || 'Meson Explorer' })
  return embeds
}

/**
 * A posted wallet list (buildUnfinishedAddressEmbeds — its embeds as posted, one per message) with every row's status brought up to date: title, colour and row headings change; the description, "Checked" and footer stay as they were.
 * `swaps` are the listed swaps' latest views, in list order; each embed keeps its own rows.
 * @param {object[]} posted the embeds' data (an EmbedBuilder or a fetched embed)
 * @returns {EmbedBuilder[]}
 */
export function relistWalletEmbeds (posted, swaps) {
  const open = swaps.filter((s) => !isFinished(s.status)).length
  let n = 0
  return posted.map((old, i) => {
    // Rebuilt from what buildUnfinishedAddressEmbeds sets, not copied: an embed fetched from Discord also carries read-only keys (type, scan data) that an edit must not send back.
    const embed = new EmbedBuilder().setURL(old.url ?? null).setDescription(old.description || null)
    if (old.footer?.text) embed.setFooter({ text: old.footer.text })
    const fields = (old.fields ?? []).map((f) => {
      if (!WALLET_ROW.test(f.name)) return { name: f.name, value: f.value }
      const swap = swaps[n++]
      return swap ? { name: walletRowName(swap, n), value: walletRowValue(swap) } : { name: f.name, value: f.value }
    })
    return embed
      .setColor(open ? COLOR.pending : COLOR.ok)
      .setTitle(walletTitle(open, swaps.length, posted.length > 1 ? `${i + 1}/${posted.length}` : null))
      .setFields(fields)
  })
}

// =============================================================================
//   Not-found embed
// =============================================================================

/** Shown when nothing lookupable was found or the swap does not exist. */
export function buildNotFoundEmbed (query, { hint } = {}) {
  return new EmbedBuilder()
    .setColor(COLOR.bad)
    .setTitle('No Meson swap found')
    .setDescription(
      (query ? `I could not find a swap for ${code(query)}.\n\n` : '') +
      (hint ??
        'Please paste one of:\n' +
        '• the **swap ID** (`0x` + 64 characters)\n' +
        '• the **transaction hash** from either chain\n' +
        '• the **Meson explorer link** for the swap\n\n' +
        'A swap can also take a moment to appear right after it is submitted.')
    )
}

// =============================================================================
//   Recognising our own messages
// =============================================================================

// Restart recovery (recover.js) rebuilds a ticket from the messages above, so these must change together with the builders: a message they no longer recognise is not recovered.

/** The swap ID of a swap details embed (buildSwapEmbed: title "Meson swap …", URL = the swap's explorer link), or null for any other embed; `limited` if it was built from the relayer stand-in (title ends in LIMITED_TAG), so its ⏳ / 🔎 / closing message was never posted. Its "#n" is its posting order, not read back. */
export function readSwapEmbed (embed) {
  const id = embed?.title?.startsWith('Meson swap') && embed.url?.match(/\/swap\/(0x[0-9a-fA-F]{64})$/)
  return id ? { swapId: id[1].toLowerCase(), limited: embed.title.endsWith(LIMITED_TAG) } : null
}

/** The wallet address of a wallet embed (buildUnfinishedAddressEmbeds: URL = the address's explorer page), or null. */
export const readWalletEmbed = (embed) => embed?.url?.match(/explorer\.meson\.fi\/address\/([^/?#]+)$/)?.[1] ?? null

/** A wallet-list row's heading (walletRowName: "1) 🟡 Releasing"). Lists posted before rows were numbered have none, so their swaps are not taken for followed ones. */
const WALLET_ROW = /^\d+\) /

/** The swap IDs a wallet embed lists (lower case, in order) — the rows its numbered headings mark (walletRowName / walletRowValue); none for a list without numbered rows. */
export function readWalletRows (embed) {
  return (embed?.fields ?? [])
    .filter((f) => WALLET_ROW.test(f.name))
    .map((f) => f.value.match(/\/swap\/(0x[0-9a-fA-F]{64})\)/)?.[1]?.toLowerCase())
    .filter(Boolean)
}

/**
 * The values a message of ours told the user cannot be found: those in a ❓ reply (buildSwapNotFoundMessage), or in a wallet embed's "Could not find" line (buildUnfinishedAddressEmbeds).
 * Past codeList's limit the rest are only counted, so after a restart those few could be answered once more.
 */
export function readToldValues (message) {
  const line = message.content?.startsWith('❓')
    ? message.content.split('\n')[0]
    : message.embeds?.[0]?.description?.split('\n').find((l) => l.startsWith('Could not find a swap for')) ?? ''
  return [...line.matchAll(/`([^`]+)`/g)].map((m) => m[1])
}

/** Which outage notice a plain-text message is ('wallet' or 'swap', buildOutageNotice), or null — so a restart does not post it to the ticket again. */
export const outageNoticeKind = (content = '') => Object.keys(OUTAGE_NOTICES).find((kind) => content === OUTAGE_NOTICES[kind]) ?? null

/** Which outcome a closing message of ours (buildOutcomeMessage) announced — 'completed' (✅) or 'cancelled' (↩️) — or null for any other message. */
export function readOutcomeKind (content = '') {
  if (content.startsWith('**✅')) return 'completed'
  if (content.startsWith('**↩️')) return 'cancelled'
  return null
}

/** Which follow-up a plain-text message is: ⏳ (buildProcessingMessage), 🔎 (buildSupportMessage) or ✅ / ↩️ (buildOutcomeMessage) — or null. */
export function followUpKind (content = '') {
  if (content.startsWith('⏳')) return 'processing'
  if (content.startsWith('🔎')) return 'support'
  if (content.startsWith('**✅') || content.startsWith('**↩️')) return 'outcome'
  return null
}
